{
  "$schema": "https://modelcontextprotocol.io/schema/server.json",
  "name": "roshan-fahm-mcp",
  "description": "Self-hostable MCP server for Roshan AI's Fahm (فهم) Persian language service: chat over documents/media, translation, summarization, text generation, correction, document classification and information extraction. Supports many named, self-hosted instances.",
  "version": "0.2.0",
  "homepage": "https://www.roshan-ai.ir",
  "documentation": "https://docs.roshan-ai.ir",
  "license": "MIT",
  "runtime": {
    "type": "python",
    "python": ">=3.10",
    "entrypoint": "python -m roshan_fahm_mcp"
  },
  "transports": ["stdio", "sse", "streamable-http"],
  "environment_variables": [
    {
      "name": "ROSHAN_FAHM__DEFAULT_INSTANCE",
      "description": "Name of the instance used when a tool call omits 'instance'.",
      "required": false,
      "default": "default"
    },
    {
      "name": "ROSHAN_FAHM__LOG_LEVEL",
      "description": "Logging level (DEBUG/INFO/WARNING/ERROR).",
      "required": false,
      "default": "INFO"
    },
    {
      "name": "ROSHAN_FAHM__INSTANCES__<NAME>__BASE_URL",
      "description": "Fahm host root for instance <NAME> (default https://fahm.roshan-ai.ir; endpoints are under /api/..., login under /auth/glogin/).",
      "required": false
    },
    {
      "name": "ROSHAN_FAHM__INSTANCES__<NAME>__USERNAME",
      "description": "Fahm username for instance <NAME> (exchanged for a Bearer access_token via POST /auth/glogin/).",
      "required": false,
      "secret": true
    },
    {
      "name": "ROSHAN_FAHM__INSTANCES__<NAME>__PASSWORD",
      "description": "Fahm password for instance <NAME> (exchanged for a Bearer access_token via POST /auth/glogin/).",
      "required": false,
      "secret": true
    },
    {
      "name": "ROSHAN_FAHM__INSTANCES__<NAME>__TOKEN",
      "description": "Static Bearer access token for instance <NAME> (alternative to username/password).",
      "required": false,
      "secret": true
    },
    {
      "name": "ROSHAN_FAHM__INSTANCES__<NAME>__VERIFY_SSL",
      "description": "Whether to verify TLS for instance <NAME> (default true; set false for self-signed dev hosts).",
      "required": false,
      "default": "true"
    },
    {
      "name": "ROSHAN_FAHM__INSTANCES__<NAME>__TIMEOUT",
      "description": "Per-request timeout in seconds for instance <NAME> (default 60).",
      "required": false,
      "default": "60"
    },
    {
      "name": "ROSHAN_FAHM_BASE_URL",
      "description": "Shorthand: Fahm host root for the default instance.",
      "required": false
    },
    {
      "name": "ROSHAN_FAHM_USERNAME",
      "description": "Shorthand: Fahm username for the default instance (POST /auth/glogin/).",
      "required": false,
      "secret": true
    },
    {
      "name": "ROSHAN_FAHM_PASSWORD",
      "description": "Shorthand: Fahm password for the default instance (POST /auth/glogin/).",
      "required": false,
      "secret": true
    },
    {
      "name": "ROSHAN_FAHM_TOKEN",
      "description": "Shorthand: static Bearer access token for the default instance.",
      "required": false,
      "secret": true
    }
  ],
  "tools": [
    { "name": "fahm_chat", "description": "Chat with Fahm's LLM, optionally grounded on document/media URLs (deep research + search_mode)." },
    { "name": "fahm_list_chats", "description": "List chats/service history, or fetch the history of one chat by id." },
    { "name": "fahm_translate_text", "description": "Translate text into Persian (fa) or English (en)." },
    { "name": "fahm_translate_documents", "description": "Translate Alefba document URLs into Persian or English." },
    { "name": "fahm_translate", "description": "Ergonomic wrapper: translate text OR documents into Persian/English." },
    { "name": "fahm_summarize", "description": "Summarize text or documents as prose (word) or a bullet list (bullet)." },
    { "name": "fahm_summarize_document", "description": "Ergonomic wrapper: summarize Alefba documents (word or bullet)." },
    { "name": "fahm_generate_letter", "description": "Generate a piece of text (e.g. a letter) from a topic." },
    { "name": "fahm_correct_text", "description": "Correct and edit text per a free-form instruction." },
    { "name": "fahm_classify", "description": "Classify Alefba documents into supplied labels." },
    { "name": "fahm_extract_information", "description": "Answer questions over several Alefba documents." },
    { "name": "healthcheck", "description": "Probe connectivity/health of an instance (GET /api/healthcheck)." },
    { "name": "list_instances", "description": "List configured instances and base URLs (no secrets)." },
    { "name": "roshan_fahm_docs", "description": "Built-in documentation for Fahm and this server's tools." }
  ]
}
